function netWorth(assets, liabilities){
  var a=0,al=0; for(var i=0;i<assets.length;i++) a+= (+assets[i]||0);
  for(var j=0;j<liabilities.length;j++) al+= (+liabilities[j]||0);
  return {assets:a, liabilities:al, net:a-al};
}
function parseNums(t){ var out=[]; t.split(/[\n,]/).forEach(function(s){ var x=parseFloat(s.trim()); if(!isNaN(x)) out.push(x); }); return out; }
var EXPORTS={netWorth:netWorth, parseNums:parseNums};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.NetWorthForgePure = EXPORTS; }
